%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_setBasic %[output:09c0e256]
VehSpdRef_setSimCase_Constant( ... %[output:group:7ab880cc] %[output:872d0e7e]
  ModelName = modelName, ... %[output:872d0e7e]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:7ab880cc] %[output:872d0e7e]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData, PlotTemperature = false); %[output:7acb40fe]
